<script setup lang="ts">
const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
type Aspect='access'|'economics'|'trust'|'replaceability'
type Side='current'|'web'|'open'
type Node={id:string;titleNl:string;titleEn:string;ownerNl:string;ownerEn:string;detailNl:string;detailEn:string;kind:'publisher'|'private'|'layer'|'ai'|'user'}
const aspect=ref<Aspect>('access'),alternative=ref<'web'|'open'>('web'),selected=ref<{side:Side,id:string}>({side:'current',id:'private-index'}),failure=ref(false)
const tabs=[
 {id:'access' as Aspect,nl:'Toegang en zeggenschap',en:'Access and control'},
 {id:'economics' as Aspect,nl:'Gebruik en vergoeding',en:'Use and compensation'},
 {id:'trust' as Aspect,nl:'Herkomst en vertrouwen',en:'Provenance and trust'},
 {id:'replaceability' as Aspect,nl:'Vervangbaarheid',en:'Replaceability'}
]
const common={
 publishers:{id:'publishers',titleNl:'Bron en gebruiksrechten',titleEn:'Source and usage rights',ownerNl:'Maker of rechthebbende',ownerEn:'Creator or rights holder',detailNl:'Publiceert een herkenbare, actuele bron en geeft aan welk gebruik onder welke voorwaarden is toegestaan.',detailEn:'Publishes an identifiable, current source and specifies permitted uses and terms.',kind:'publisher'} as Node,
 users:{id:'users',titleNl:'Mensen en toepassingen',titleEn:'People and applications',ownerNl:'De gebruiker kiest een interface',ownerEn:'The user chooses an interface',detailNl:'Ontvangen links, bronnen of een samengesteld antwoord.',detailEn:'Receive links, sources or a synthesized answer.',kind:'user'} as Node
}
const diagrams=computed<Record<Aspect,Record<Side,Node[]>>>(()=>({
 access:{
  current:[common.publishers,{id:'private-index',titleNl:'Private crawl- en kennislaag',titleEn:'Private crawl and knowledge layer',ownerNl:'Iedere AI-aanbieder afzonderlijk',ownerEn:'Each AI provider separately',detailNl:'De aanbieder bepaalt wat wordt gecrawld, bewaard, ververst en doorzoekbaar gemaakt.',detailEn:'The provider decides what is crawled, retained, refreshed and made searchable.',kind:'private'},{id:'ai-provider',titleNl:'Model en interface van dezelfde aanbieder',titleEn:'Model and interface from the same provider',ownerNl:'Eén commerciële of publieke exploitant',ownerEn:'One commercial or public operator',detailNl:'Retrieval, selectie, synthese en presentatie zitten grotendeels in dezelfde verticale keten.',detailEn:'Retrieval, selection, synthesis and presentation largely sit in one vertical stack.',kind:'ai'},common.users],
  web:[common.publishers,{id:'web-index',titleNl:'Webpagina met metadata; eigen zoekindexen',titleEn:'Web page with metadata; separate search indexes',ownerNl:'Uitgevers en onafhankelijke zoekdiensten',ownerEn:'Publishers and independent search services',detailNl:'Een maker publiceert bron, versie en voorwaarden op de eigen website. Elke zoekdienst ontdekt en indexeert die gegevens zelf en kan andere tekst- of vectorrepresentaties maken.',detailEn:'Creators publish source, version and terms on their own websites. Each search service discovers and indexes that data independently, with its own text or vector representations.',kind:'layer'},{id:'web-ai',titleNl:'AI-toepassing naar keuze',titleEn:'AI application of choice',ownerNl:'Meerdere aanbieders of een lokaal model',ownerEn:'Multiple providers or a local model',detailNl:'Waar het model draait en waar het zoekt zijn afzonderlijke keuzes.',detailEn:'Where the model runs and where it searches are separate choices.',kind:'ai'},common.users],
  open:[common.publishers,{id:'open-layer',titleNl:'Gedeelde toegang, meerdere zoekindexen',titleEn:'Shared access, multiple search indexes',ownerNl:'Open afspraken, onafhankelijke diensten',ownerEn:'Open agreements, independent services',detailNl:'Een open aansluiting koppelt bron en versie aan zoekresultaten, gebruikte methode en oorspronkelijke passage. Meerdere vectorrepresentaties en zoekdiensten kunnen naast elkaar bestaan.',detailEn:'An open interface links source and version to search results, the method used and the original passage. Multiple vector representations and search providers can coexist.',kind:'layer'},{id:'competing-ai',titleNl:'AI-toepassingen naar keuze',titleEn:'AI applications of choice',ownerNl:'Meerdere aanbieders of een lokaal model',ownerEn:'Multiple providers or a local model',detailNl:'Modellen vinden dezelfde bronnen en passen eigen selectie- en bewijsregels toe. De rekenlocatie staat los van de zoekdienst.',detailEn:'Models find the same sources and apply their own selection and evidence rules. Inference location is separate from search.',kind:'ai'},common.users]
 },
 economics:{
  current:[common.publishers,{id:'crawl-answer',titleNl:'Crawlen en antwoord overnemen',titleEn:'Crawl and answer directly',ownerNl:'Private AI-keten',ownerEn:'Private AI stack',detailNl:'De aanbieder kan informatie gebruiken zonder dat een bezoek aan de bron volgt. Licenties en betaalmodellen verschillen per platform.',detailEn:'The provider may use information without a visit to the source. Licensing and payment models differ by platform.',kind:'private'},{id:'limited-return',titleNl:'Beperkte terugstroom',titleEn:'Limited return flow',ownerNl:'Afhankelijk van citaten, links en productontwerp',ownerEn:'Depends on citations, links and product design',detailNl:'De maker ontvangt mogelijk bereik, verkeer, betaling of niets; dit is niet door een open protocol vastgelegd.',detailEn:'The creator may receive reach, traffic, payment or nothing; no open protocol defines the exchange.',kind:'ai'},common.users],
  web:[common.publishers,{id:'web-policy',titleNl:'Voorwaarden op de webpagina',titleEn:'Terms on the web page',ownerNl:'Maker publiceert machineleesbare regels',ownerEn:'Creator publishes machine-readable terms',detailNl:'Vindbaar maken, ophalen, tonen en trainen kunnen verschillende voorwaarden hebben. Alleen publiceren registreert gebruik of betaling niet automatisch.',detailEn:'Discovery, retrieval, display and training can have distinct terms. Publishing terms alone does not record use or payment.',kind:'layer'},{id:'web-payment',titleNl:'AI-diensten met eigen afspraken',titleEn:'AI services with their own agreements',ownerNl:'Aanbieders en rechthebbenden',ownerEn:'Providers and rights holders',detailNl:'De dienst moet zelf toestemming en eventuele betaling regelen; metadata dwingen naleving niet af.',detailEn:'Each service must arrange permissions and any payment; metadata does not enforce compliance.',kind:'ai'},common.users],
  open:[common.publishers,{id:'publisher-policy',titleNl:'Gebruiksvoorwaarden en mogelijke afrekening',titleEn:'Usage terms and possible settlement',ownerNl:'Afzonderlijke afspraken en gedeelde diensten',ownerEn:'Separate agreements and shared services',detailNl:'Een dienst kan overeengekomen vormen van gebruik registreren. Meting, privacy, rechthebbenden, vergoeding en geschillen vergen afzonderlijke afspraken.',detailEn:'A service could record agreed forms of use. Measurement, privacy, rights holders, compensation and disputes require separate agreements.',kind:'layer'},{id:'accountable-use',titleNl:'Gebruik door verschillende AI-diensten',titleEn:'Use by multiple AI services',ownerNl:'Geen verplicht verdienmodel',ownerEn:'No mandatory business model',detailNl:'Een technisch protocol bepaalt geen eerlijke prijs of juridisch recht op betaling; gebruik moet controleerbaar zijn.',detailEn:'A technical protocol cannot establish a fair price or legal entitlement to payment; usage needs to be auditable.',kind:'ai'},common.users]
 },
 trust:{
  current:[common.publishers,{id:'opaque-selection',titleNl:'Private selectie en metadata',titleEn:'Private selection and metadata',ownerNl:'De AI-aanbieder',ownerEn:'The AI provider',detailNl:'Buitenstaanders zien beperkt welke versies, relaties en herkomstgegevens in de index zijn behouden.',detailEn:'Outsiders have limited visibility into which versions, relations and provenance data the index retains.',kind:'private'},{id:'combined-trust',titleNl:'Relevantie en vertrouwen in één product',titleEn:'Relevance and trust in one product',ownerNl:'Productbeleid en modelgedrag',ownerEn:'Product policy and model behaviour',detailNl:'Hetzelfde systeem vindt informatie en bepaalt hoe zwaar die wordt gewogen.',detailEn:'The same system finds information and decides how heavily to weigh it.',kind:'ai'},common.users],
  web:[common.publishers,{id:'web-provenance',titleNl:'Herkomst en correcties bij de bron',titleEn:'Provenance and corrections at source',ownerNl:'Uitgever en eigen website',ownerEn:'Publisher and own website',detailNl:'De maker kan versies en correcties publiceren. Elke zoekdienst moet die zelf verwerken; herkomst bewijst niet dat inhoud waar is.',detailEn:'Creators can publish versions and corrections. Each search service must process them; provenance does not prove a claim true.',kind:'layer'},{id:'web-trust',titleNl:'Onafhankelijke bewijsregels',titleEn:'Independent evidence policies',ownerNl:'Elke AI-toepassing',ownerEn:'Each AI application',detailNl:'De toepassing beslist welke bronnen voldoende onderbouwing bieden.',detailEn:'The application decides which sources provide sufficient evidence.',kind:'ai'},common.users],
  open:[common.publishers,{id:'identity-provenance',titleNl:'Gedeelde signalen over versies',titleEn:'Shared version signals',ownerNl:'Webpublicaties en gedeelde afspraken',ownerEn:'Web publications and shared agreements',detailNl:'Kan zichtbaar maken wie iets publiceerde, welke versie is gebruikt en welke correcties beschikbaar zijn. Deelnemende zoekdiensten moeten die signalen wel verwerken; herkomst bewijst geen waarheid.',detailEn:'Can show who published something, which version was used and which corrections are available. Participating search services must still process these signals; provenance does not prove truth.',kind:'layer'},{id:'separate-trust',titleNl:'Meerdere vertrouwens- en rankingstelsels',titleEn:'Multiple trust and ranking systems',ownerNl:'Gebruiker, domein of AI-aanbieder kiest',ownerEn:'Chosen by user, domain or AI provider',detailNl:'Een medische assistent kan andere bewijsregels gebruiken dan een winkel- of restaurantassistent.',detailEn:'A medical assistant may use different evidence policies from a shopping or restaurant assistant.',kind:'ai'},common.users]
 },
 replaceability:{
  current:[common.publishers,{id:'duplicated-stack',titleNl:'Herhaalde private infrastructuur',titleEn:'Duplicated private infrastructure',ownerNl:'Elke aanbieder bouwt opnieuw',ownerEn:'Each provider rebuilds it',detailNl:'Nieuwe modellen moeten crawling, opslag, indexering en relaties grotendeels opnieuw organiseren.',detailEn:'New models must largely recreate crawling, storage, indexing and relationships.',kind:'private'},{id:'single-provider',titleNl:'Aanbieder als toegangspoort',titleEn:'Provider as gateway',ownerNl:'Kennislaag en model zijn verweven',ownerEn:'Knowledge layer and model are intertwined',detailNl:'Bij prijswijziging, uitsluiting of uitval is overstappen moeilijker omdat ook de toegangsinfrastructuur verandert.',detailEn:'Price changes, exclusion or failure make switching harder because the access infrastructure changes too.',kind:'ai'},common.users],
  web:[common.publishers,{id:'web-switch',titleNl:'Web met eigen indexen',titleEn:'Web with separate indexes',ownerNl:'Uitgevers houden hun website',ownerEn:'Publishers retain their websites',detailNl:'Een vervangende AI-dienst kan dezelfde pagina’s vinden, maar moet een eigen index en gebruiksafspraken regelen.',detailEn:'A replacement AI service can find the same pages but must arrange its own index and usage agreements.',kind:'layer'},{id:'web-replacement',titleNl:'Vervangbare AI-toepassing',titleEn:'Replaceable AI application',ownerNl:'Gebruiker kiest aanbieder of lokaal model',ownerEn:'User chooses provider or local model',detailNl:'Publicaties blijven op het web beschikbaar wanneer een AI-dienst wegvalt.',detailEn:'Publications remain on the web when an AI service fails.',kind:'ai'},common.users],
  open:[common.publishers,{id:'durable-layer',titleNl:'Duurzame bronafspraken, meerdere indexen',titleEn:'Durable source agreements, multiple indexes',ownerNl:'Bestaande websites en onafhankelijke diensten',ownerEn:'Existing websites and independent services',detailNl:'De bronidentiteit blijft bestaan wanneer zoekindex, embeddingmodel of AI-toepassing wordt vervangen. Onderhoud van gedeelde diensten blijft nodig.',detailEn:'Source identity survives replacement of search index, embedding model or AI application. Shared services still need maintenance.',kind:'layer'},{id:'replaceable-ai',titleNl:'Vervangbaar model en interface',titleEn:'Replaceable model and interface',ownerNl:'Concurrentie boven gedeelde toegang',ownerEn:'Competition over shared access',detailNl:'Een nieuwe aanbieder kan bestaande bronnen en diensten gebruiken zonder opnieuw het hele web te verzamelen; eigen zoektechniek blijft mogelijk.',detailEn:'A new provider can use existing sources and services without collecting the whole web again; independent search technology remains possible.',kind:'ai'},common.users]
 }
}))
const activeNode=computed(()=>diagrams.value[aspect.value][selected.value.side].find(n=>n.id===selected.value.id)||diagrams.value[aspect.value][selected.value.side][1])
const visibleSides=computed<Side[]>(()=>['current',alternative.value])
const sideNames=computed<Record<Side,string>>(()=>({current:nl.value?'Private productketen':'Private product stack',web:nl.value?'Bestaand web met metadata':'Existing web with metadata',open:nl.value?'Web met gedeelde diensten':'Web with shared services'}))
function chooseAspect(id:Aspect){aspect.value=id;selected.value={side:'current',id:diagrams.value[id].current[1].id};failure.value=false}
function chooseAlternative(side:'web'|'open'){alternative.value=side;selected.value={side,id:diagrams.value[aspect.value][side][1].id};failure.value=false}
function select(side:Side,node:Node){selected.value={side,id:node.id}}
</script>

<template>
 <section class="knowledge-explorer">
  <header><div><p>{{nl?'Interactieve architectuurvergelijking':'Interactive architecture comparison'}}</p><h3>{{nl?'Hoe komen bronnen bij een AI-antwoord?':'How do sources reach an AI answer?'}}</h3></div><button type="button" @click="chooseAlternative('web');chooseAspect('access')">{{nl?'Herstel beginweergave':'Reset view'}}</button></header>
  <p class="intro">{{nl?'Vergelijk een private keten met bestaande websites plus metadata, of met gedeelde diensten bovenop die websites. Klik op een stap voor de gevolgen.':'Compare a private stack with existing websites plus metadata, or with shared services connected to those websites. Select a step to see its implications.'}}</p>
  <div class="alternative-picker" role="group" :aria-label="nl?'Kies alternatief':'Choose alternative'"><span>{{nl?'Vergelijk met':'Compare with'}}</span><button type="button" :aria-pressed="alternative==='web'" :class="{active:alternative==='web'}" @click="chooseAlternative('web')">{{sideNames.web}}</button><button type="button" :aria-pressed="alternative==='open'" :class="{active:alternative==='open'}" @click="chooseAlternative('open')">{{sideNames.open}}</button></div>
  <nav :aria-label="nl?'Vergelijkingsperspectief':'Comparison perspective'"><button v-for="tab in tabs" :key="tab.id" :class="{active:aspect===tab.id}" @click="chooseAspect(tab.id)">{{nl?tab.nl:tab.en}}</button></nav>
  <div class="architectures">
   <article v-for="side in visibleSides" :key="side" :class="['architecture',side,{failed:failure&&side==='current'&&aspect==='replaceability'}]">
    <div class="architecture-head"><span>{{side==='current'?(nl?'Veelgebruikte huidige architectuur':'Common current architecture'):(nl?'Mogelijk alternatief':'Possible alternative')}}</span><b>{{sideNames[side]}}</b></div>
    <div class="flow">
     <template v-for="(node,index) in diagrams[aspect][side]" :key="node.id">
      <button type="button" :class="['node',node.kind,{active:selected.side===side&&selected.id===node.id}]" @click="select(side,node)"><span>{{nl?node.titleNl:node.titleEn}}</span><small>{{nl?node.ownerNl:node.ownerEn}}</small></button>
      <span v-if="index<diagrams[aspect][side].length-1" class="arrow" aria-hidden="true">↓</span>
     </template>
    </div>
    <p v-if="failure&&side==='current'&&aspect==='replaceability'" class="failure-note">{{nl?'De toegangsketen valt mee uit of moet bij een overstap grotendeels opnieuw worden opgebouwd.':'The access stack fails with the provider or must largely be rebuilt when switching.'}}</p>
    <p v-if="failure&&side==='web'&&aspect==='replaceability'" class="failure-note resilient">{{nl?'De websites blijven bereikbaar. Een vervangende dienst moet zelf zoeken en indexeren.':'The websites remain accessible. A replacement service must build its own search and index.'}}</p>
    <p v-if="failure&&side==='open'&&aspect==='replaceability'" class="failure-note resilient">{{nl?'De bronnen en afspraken blijven beschikbaar zolang onafhankelijke diensten ze onderhouden.':'Sources and agreements remain available as long as independent services maintain them.'}}</p>
   </article>
  </div>
  <button v-if="aspect==='replaceability'" class="failure-toggle" type="button" :aria-pressed="failure" @click="failure=!failure">{{failure?(nl?'Herstel aanbieder':'Restore provider'):(nl?'Simuleer uitval of overstap':'Simulate failure or switching')}}</button>
  <aside class="detail"><div><span>{{sideNames[selected.side]}}</span><h4>{{nl?activeNode.titleNl:activeNode.titleEn}}</h4></div><p>{{nl?activeNode.detailNl:activeNode.detailEn}}</p></aside>
  <div class="layer-principles"><div><b>{{nl?'Publicatie en rechten':'Publication and rights'}}</b><span>{{nl?'Bron, versie en voorwaarden':'Source, version and terms'}}</span></div><div><b>{{nl?'Zoeken en representeren':'Search and representation'}}</b><span>{{nl?'Meerdere indexen en embeddings':'Multiple indexes and embeddings'}}</span></div><div><b>{{nl?'AI-toepassing':'AI application'}}</b><span>{{nl?'Selectie en antwoord':'Selection and answer'}}</span></div></div>
  <details><summary>{{nl?'Wat dit schema niet beweert':'What this diagram does not claim'}}</summary><p>{{nl?'Een gedeelde dienst moet nog steeds worden onderhouden en betaald. Metadata dwingen naleving niet af, een herkomstlabel bewijst geen waarheid en een open interface garandeert geen eerlijke vergoeding. Bestaande websites en gedeelde diensten kunnen samengaan.':'A shared service still needs maintenance and funding. Metadata does not enforce compliance, provenance does not prove truth, and an open interface does not guarantee fair payment. Existing websites and shared services can coexist.'}}</p></details>
 </section>
</template>

